func NewVisualStateChangedEventHandler(fn func(sender *syswinrt.IInspectable, e *IVisualStateChangedEventArgs)) (*VisualStateChangedEventHandler, error) {
	delegate, err := winrt.NewDelegate(IID_VisualStateChangedEventHandler, 2, func(raw []uintptr) uintptr {
		fn((*syswinrt.IInspectable)(unsafe.Pointer(raw[0])), (*IVisualStateChangedEventArgs)(unsafe.Pointer(raw[1])))
		return 0
	})
	if err != nil {
		return nil, err
	}
	return &VisualStateChangedEventHandler{delegate: delegate}, nil
}

// Ptr is the COM object pointer an Add<Event> method registers.
func (h *VisualStateChangedEventHandler) Ptr() uintptr { return h.delegate.Ptr() }

// Close releases the Go-held reference. Call it once no native code can still
// invoke the handler — after the event source removed it, or closed. The runtime
// keeps its own references while the handler stays registered.
func (h *VisualStateChangedEventHandler) Close() { h.delegate.Release() }
